        answer = try c.decode(AccessRequestAnswer?.self, forKey: "answer")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(requestId, forKey: "request_id")
        try c.encode(clientId, forKey: "client_id")
        try c.encode(deviceName, forKey: "device_name")
        try c.encodeIfPresent(ownerLabel, forKey: "owner_label")
        try c.encodeIfPresent(profileKind, forKey: "profile_kind")
        try c.encodeIfPresent(note, forKey: "note")
        try c.encode(status, forKey: "status")
        try c.encode(createdAt, forKey: "created_at")
        try c.encode(expiresAt, forKey: "expires_at")
