        tls = try c.decodeIfPresent(String.self, forKey: "tls")
        tlsPort = try c.decodeIfPresent(String.self, forKey: "tls_port")
        fp = try c.decodeIfPresent(String.self, forKey: "fp")
        version = try c.decode(String.self, forKey: "version")
        iid = try c.decode(String.self, forKey: "iid")
        pv = try c.decode(String.self, forKey: "pv")
        pvMin = try c.decode(String.self, forKey: "pv_min")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(wsPath, forKey: "ws_path")
        try c.encode(apiPath, forKey: "api_path")
        try c.encodeIfPresent(appUrl, forKey: "app_url")
        try c.encodeIfPresent(tls, forKey: "tls")
        try c.encodeIfPresent(tlsPort, forKey: "tls_port")
        try c.encodeIfPresent(fp, forKey: "fp")
        try c.encode(version, forKey: "version")
        try c.encode(iid, forKey: "iid")
        try c.encode(pv, forKey: "pv")
        try c.encode(pvMin, forKey: "pv_min")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/ws_path", wsPath, const: "/api/ws")
        ContractCheck.string(&v_, path + "/api_path", apiPath, const: "/api")
        ContractCheck.string(&v_, path + "/tls", tls, const: "1")
        ContractCheck.string(&v_, path + "/tls_port", tlsPort, .init(pattern: #"^[0-9]{1,5}\z"#))
        ContractCheck.string(&v_, path + "/fp", fp, .init(pattern: #"^[0-9a-f]{64}\z"#))
        ContractCheck.string(&v_, path + "/pv", pv, .init(pattern: #"^[1-9][0-9]{0,3}\z"#))
        ContractCheck.string(&v_, path + "/pv_min", pvMin, .init(pattern: #"^[1-9][0-9]{0,3}\z"#))
        var present_ = Set<String>()
        present_.insert("ws_path")
        present_.insert("api_path")
        if appUrl != nil { present_.insert("app_url") }
        if tls != nil { present_.insert("tls") }
        if tlsPort != nil { present_.insert("tls_port") }
        if fp != nil { present_.insert("fp") }
        present_.insert("version")
        present_.insert("iid")
        present_.insert("pv")
        present_.insert("pv_min")
        ContractCheck.object(&v_, path, present: present_, dependentRequired: ["fp": ["tls_port"], "tls": ["tls_port", "fp"]])
        return v_
    }
}

