        self.categories = categories
        self.`open` = `open`
        self.nextAllowedAt = nextAllowedAt
        self.recipients = recipients
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        enabled = try c.decode(Bool.self, forKey: "enabled")
        categories = try c.decode([FamilyRequestCategory].self, forKey: "categories")
        `open` = try c.decode(FamilyRequest?.self, forKey: "open")
        nextAllowedAt = try c.decode(String?.self, forKey: "next_allowed_at")
        recipients = try c.decode([ClientKidsRequestsRecipientsItem].self, forKey: "recipients")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(enabled, forKey: "enabled")
        try c.encode(categories, forKey: "categories")
        try c.encode(`open`, forKey: "open")
        try c.encode(nextAllowedAt, forKey: "next_allowed_at")
        try c.encode(recipients, forKey: "recipients")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
