        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        days = try c.decode([KidsWeekday].self, forKey: "days")
        start = try c.decode(String.self, forKey: "start")
        end = try c.decode(String.self, forKey: "end")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(days, forKey: "days")
        try c.encode(start, forKey: "start")
        try c.encode(end, forKey: "end")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.items(&v_, path + "/days", days, minItems: 1, maxItems: 7, unique: true)
        ContractCheck.nested(&v_, path + "/days", days)
        ContractCheck.string(&v_, path + "/start", start, .init(pattern: #"^([01][0-9]|2[0-3]):[0-5][0-9]\z"#))
        ContractCheck.string(&v_, path + "/end", end, .init(pattern: #"^([01][0-9]|2[0-3]):[0-5][0-9]\z"#))
        return v_
    }
}

/// Rule object of the kids mode, the same on the levels profile, area and entity. A missing field
/// is inherited from the more general level (entity -> area -> profile); null for
/// rate_limit/volume_max switches the rule off on that level. Access: entity blocked, else area
/// blocked, else effective blocked_types (area, else profile), else profile blocked. An entity
/// placed in several visible areas is checked per area; any block wins. blocked_types is not
/// allowed on the entity level (422 rules.blocked_types). Invalid objects: 422 with detail
/// rules.<field>.
/// Schema: `schemas/common/kids-rules.json`.
public struct KidsRules: ContractValue {
    /// true = everything in this scope blocked; false = explicitly allowed (overrides blocked_types and
    /// blocked of the more general levels).
    public var blocked: Bool?
    /// Profile and area only; on the area level it replaces the profile's list.
    public var blockedTypes: [String]?
    /// Bedtime windows; [] = no bedtime on this level (exception, e.g. a night light).
    public var quietHours: [QuietHoursWindow]?
    public var rateLimit: KidsRateLimit?
    /// Lights: no rgb/rgbw/rgbww/hs/xy color, color_name, effect, flash. On/off, brightness and
    /// color_temp_kelvin stay allowed.
    public var colorLock: Bool?
    /// Volume cap in percent for media_player: volume_set above it is set to the cap (answer adjusted),
    /// volume_up at the cap is rejected (volume_limit), just below it becomes volume_set(cap); unknown
    /// volume rejects volume_up.
    public var volumeMax: Int?

    public init(
        blocked: Bool? = nil,
        blockedTypes: [String]? = nil,
        quietHours: [QuietHoursWindow]? = nil,
        rateLimit: KidsRateLimit? = nil,
        colorLock: Bool? = nil,
        volumeMax: Int? = nil
    ) {
        self.blocked = blocked
        self.blockedTypes = blockedTypes
        self.quietHours = quietHours
        self.rateLimit = rateLimit
        self.colorLock = colorLock
        self.volumeMax = volumeMax
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        blocked = try c.decodeIfPresent(Bool.self, forKey: "blocked")
        blockedTypes = try c.decodeIfPresent([String].self, forKey: "blocked_types")
        quietHours = try c.decodeIfPresent([QuietHoursWindow].self, forKey: "quiet_hours")
        rateLimit = try c.decodeIfPresent(KidsRateLimit.self, forKey: "rate_limit")
        colorLock = try c.decodeIfPresent(Bool.self, forKey: "color_lock")
        volumeMax = try c.decodeIfPresent(Int.self, forKey: "volume_max")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encodeIfPresent(blocked, forKey: "blocked")
        try c.encodeIfPresent(blockedTypes, forKey: "blocked_types")
        try c.encodeIfPresent(quietHours, forKey: "quiet_hours")
        try c.encodeIfPresent(rateLimit, forKey: "rate_limit")
        try c.encodeIfPresent(colorLock, forKey: "color_lock")
        try c.encodeIfPresent(volumeMax, forKey: "volume_max")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.items(&v_, path + "/blocked_types", blockedTypes, maxItems: 30, unique: true)
        for (i0_, x0_) in (blockedTypes ?? []).enumerated() {
            ContractCheck.string(&v_, "\(path + "/blocked_types")/\(i0_)", x0_, .init(pattern: #"^[a-z0-9_]{1,64}(:[a-z0-9_]{1,64})?\z"#))
        }
        ContractCheck.items(&v_, path + "/quiet_hours", quietHours, maxItems: 14)
        ContractCheck.nested(&v_, path + "/quiet_hours", quietHours)
        ContractCheck.nested(&v_, path + "/rate_limit", rateLimit)
        ContractCheck.number(&v_, path + "/volume_max", volumeMax, minimum: 0, maximum: 100)
        return v_
    }
}

