/// Visible areas. all = every active area; selected = the listed areas, areas with one of the tags
/// and (own_area) the device's own area; nothing selected = no area (fail closed). In resolved
/// values (client_config) the hub has replaced own_area by the concrete id: own_area is always
/// false there.
public struct ProfileRuleValuesAreas: ContractValue {
    public var mode: ProfileRuleValuesAreasMode
    public var areaIds: [String]?
    public var tags: [String]?
    public var ownArea: Bool?

    public init(
        mode: ProfileRuleValuesAreasMode,
        areaIds: [String]? = nil,
        tags: [String]? = nil,
        ownArea: Bool? = nil
    ) {
        self.mode = mode
        self.areaIds = areaIds
        self.tags = tags
        self.ownArea = ownArea
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        mode = try c.decode(ProfileRuleValuesAreasMode.self, forKey: "mode")
        areaIds = try c.decodeIfPresent([String].self, forKey: "area_ids")
        tags = try c.decodeIfPresent([String].self, forKey: "tags")
        ownArea = try c.decodeIfPresent(Bool.self, forKey: "own_area")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(mode, forKey: "mode")
        try c.encodeIfPresent(areaIds, forKey: "area_ids")
        try c.encodeIfPresent(tags, forKey: "tags")
        try c.encodeIfPresent(ownArea, forKey: "own_area")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.nested(&v_, path + "/mode", mode)
        ContractCheck.items(&v_, path + "/area_ids", areaIds, maxItems: 200, unique: true)
        for (i0_, x0_) in (areaIds ?? []).enumerated() {
            ContractCheck.string(&v_, "\(path + "/area_ids")/\(i0_)", x0_, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        }
        ContractCheck.items(&v_, path + "/tags", tags, maxItems: 50, unique: true)
        for (i0_, x0_) in (tags ?? []).enumerated() {
            ContractCheck.string(&v_, "\(path + "/tags")/\(i0_)", x0_, .init(pattern: #"^(?!\*$)(?!area:)"#, minLength: 1, maxLength: 50))
        }
        return v_
    }
}

