/// one report per 5 s, then hands the fix to the integration (client_location → device_tracker)
/// without keeping it. Answer location_report_ok or location_report_error. REST twin without a
/// socket: POST /api/client/location.
/// Schema: `schemas/ws/client/location_report.json`.
public struct ClientLocationReport: ContractValue {
    public static let type = "location_report"
    public var latitude: Double
    public var longitude: Double
    /// Horizontal accuracy in m.
    public var accuracy: Double
    public var altitude: Double?
    public var verticalAccuracy: Double?
    /// m/s.
    public var speed: Double?
    public var course: Double?
    public var batteryLevel: Int?
    /// Fix taken while the app was not in the foreground.
    public var background: Bool
    /// Time of the fix (UTC).
    public var ts: String
    /// What the app shares now (optional, like client_status.location_shared).
    public var locationShared: LocationShared?

    public init(
        latitude: Double,
        longitude: Double,
        accuracy: Double,
        altitude: Double? = nil,
        verticalAccuracy: Double? = nil,
        speed: Double? = nil,
        course: Double? = nil,
        batteryLevel: Int? = nil,
        background: Bool,
        ts: String,
        locationShared: LocationShared? = nil
    ) {
        self.latitude = latitude
        self.longitude = longitude
        self.accuracy = accuracy
        self.altitude = altitude
        self.verticalAccuracy = verticalAccuracy
        self.speed = speed
        self.course = course
        self.batteryLevel = batteryLevel
        self.background = background
        self.ts = ts
        self.locationShared = locationShared
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        latitude = try c.decode(Double.self, forKey: "latitude")
        longitude = try c.decode(Double.self, forKey: "longitude")
        accuracy = try c.decode(Double.self, forKey: "accuracy")
        altitude = try c.decodeIfPresent(Double.self, forKey: "altitude")
        verticalAccuracy = try c.decodeIfPresent(Double.self, forKey: "vertical_accuracy")
        speed = try c.decodeIfPresent(Double.self, forKey: "speed")
        course = try c.decodeIfPresent(Double.self, forKey: "course")
        batteryLevel = try c.decodeIfPresent(Int.self, forKey: "battery_level")
        background = try c.decode(Bool.self, forKey: "background")
        ts = try c.decode(String.self, forKey: "ts")
        locationShared = try c.decodeIfPresent(LocationShared.self, forKey: "location_shared")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(latitude, forKey: "latitude")
        try c.encode(longitude, forKey: "longitude")
        try c.encode(accuracy, forKey: "accuracy")
        try c.encodeIfPresent(altitude, forKey: "altitude")
        try c.encodeIfPresent(verticalAccuracy, forKey: "vertical_accuracy")
        try c.encodeIfPresent(speed, forKey: "speed")
        try c.encodeIfPresent(course, forKey: "course")
        try c.encodeIfPresent(batteryLevel, forKey: "battery_level")
        try c.encode(background, forKey: "background")
        try c.encode(ts, forKey: "ts")
        try c.encodeIfPresent(locationShared, forKey: "location_shared")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.finite(&v_, path + "/latitude", latitude)
        ContractCheck.number(&v_, path + "/latitude", latitude, minimum: -90.0, maximum: 90.0)
        ContractCheck.finite(&v_, path + "/longitude", longitude)
        ContractCheck.number(&v_, path + "/longitude", longitude, minimum: -180.0, maximum: 180.0)
        ContractCheck.finite(&v_, path + "/accuracy", accuracy)
        ContractCheck.number(&v_, path + "/accuracy", accuracy, minimum: 0.0, maximum: 100000.0)
        ContractCheck.finite(&v_, path + "/altitude", altitude)
        ContractCheck.number(&v_, path + "/altitude", altitude, minimum: -1000.0, maximum: 100000.0)
        ContractCheck.finite(&v_, path + "/vertical_accuracy", verticalAccuracy)
        ContractCheck.number(&v_, path + "/vertical_accuracy", verticalAccuracy, minimum: 0.0, maximum: 100000.0)
        ContractCheck.finite(&v_, path + "/speed", speed)
        ContractCheck.number(&v_, path + "/speed", speed, minimum: 0.0, maximum: 1000.0)
        ContractCheck.finite(&v_, path + "/course", course)
        ContractCheck.number(&v_, path + "/course", course, minimum: 0.0, maximum: 360.0)
        ContractCheck.number(&v_, path + "/battery_level", batteryLevel, minimum: 0, maximum: 100)
        ContractCheck.string(&v_, path + "/ts", ts, .init(format: "date-time"))
        ContractCheck.nested(&v_, path + "/location_shared", locationShared)
        return v_
    }
}

/// A device on the hub path (parental controls or the effective rule control_path hub; never a
/// watch) asks for the artwork of a media player; other devices read it from Home Assistant with
/// their own key. The hub reads GET /api/media_player_proxy/<entity_id> and answers media_image
/// with the same request_id; without artwork the answer is control_error {ha_error} and the app
/// shows the domain icon. There is no width hint: the media player proxy does not scale. The hub
/// answers in this order: (1) a malformed request (also a width outside 64-3840, or a request_id of
/// a request of this device still open) → control_error {invalid_request}, the open request
/// continues; (2) not a paired, active device on the hub path, or a watch → control_error
/// {not_hub_controlled}; (3) access closed, an unknown entity, an entity of another domain or
/// outside the device's scope (placed in one of its readable areas, or the run target of such a
/// tile) → control_error {not_visible}, the same answer in every case and before Home Assistant is
/// contacted or a kids rule is read; (4) a request for this entity still open, more than one per
/// second for this entity, or the device's image budget used up (x-limits hub_image_*), or a lower
/// share the hub enforces → control_error {rate_limited, retry_after}; (5) with parental controls a
/// blocked device type (kids_blocked_types) → rule_blocked {reason blocked}; (6) the hub reads the
/// image from Home Assistant with its own access, without following a redirect: an error answer, a
/// redirect, no image, more than 2 MiB or a type other than JPEG, PNG, WebP or GIF → control_error
/// {ha_error}, Home Assistant not reachable → {ha_unavailable}. The content type is normalized:
/// lower case, parameters dropped, image/jpg and image/pjpeg are image/jpeg. The answer carries the
/// image only: never a URL, a Home Assistant token or a signed image URL. The hub keeps no copy.
/// Live video is not part of the hub path. The app asks again while the tile or the detail view is
/// visible. These limits are maxima: a hub may enforce lower shares (for example of a hub-wide
/// limit of open reads) and answer rate_limited earlier; clients honor rate_limited with
/// retry_after at any time. The app asks when the state's attributes.hub_picture_id appears or
/// changes ($defs/hub_picture_id); without it it asks for nothing.
/// Schema: `schemas/ws/client/media_image_get.json`.
public struct ClientMediaImageGet: ContractValue {
    public static let type = "media_image_get"
    public var requestId: String
    /// A media_player entity; any other entity is answered with not_visible.
    public var entityId: String

    public init(
        requestId: String,
        entityId: String
    ) {
        self.requestId = requestId
        self.entityId = entityId
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        requestId = try c.decode(String.self, forKey: "request_id")
        entityId = try c.decode(String.self, forKey: "entity_id")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(requestId, forKey: "request_id")
        try c.encode(entityId, forKey: "entity_id")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/request_id", requestId, .init(minLength: 1, maxLength: 64))
        ContractCheck.string(&v_, path + "/entity_id", entityId, .init(pattern: #"^[a-z0-9_]+\.[a-z0-9_]+\z"#, maxLength: 255))
        return v_
    }
}

