        notificationType = try c.decode(NotificationItemNotificationType.self, forKey: "notification_type")
        popup = try c.decode(Bool.self, forKey: "popup")
        popupMode = try c.decode(NotificationItemPopupMode.self, forKey: "popup_mode")
        scheduledAt = try c.decodeIfPresent(String.self, forKey: "scheduled_at")
        priority = try c.decode(Int.self, forKey: "priority")
        color = try c.decode(NotificationItemColor.self, forKey: "color")
        actionType = try c.decode(NotificationItemActionType.self, forKey: "action_type")
        actionTarget = try c.decodeIfPresent(String.self, forKey: "action_target")
        showTime = try c.decode(Bool.self, forKey: "show_time")
        createdAt = try c.decodeIfPresent(String.self, forKey: "created_at")
        status = try c.decodeIfPresent(NotificationItemStatus.self, forKey: "status")
        icon = try c.decodeIfPresent(String.self, forKey: "icon")
        iconSvg = try c.decodeIfPresent(String.self, forKey: "icon_svg")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(notificationId, forKey: "notification_id")
        try c.encode(title, forKey: "title")
        try c.encodeIfPresent(message, forKey: "message")
        try c.encode(notificationType, forKey: "notification_type")
        try c.encode(popup, forKey: "popup")
        try c.encode(popupMode, forKey: "popup_mode")
        try c.encodeIfPresent(scheduledAt, forKey: "scheduled_at")
        try c.encode(priority, forKey: "priority")
        try c.encode(color, forKey: "color")
        try c.encode(actionType, forKey: "action_type")
        try c.encodeIfPresent(actionTarget, forKey: "action_target")
        try c.encode(showTime, forKey: "show_time")
        try c.encodeIfPresent(createdAt, forKey: "created_at")
        try c.encodeIfPresent(status, forKey: "status")
        try c.encodeIfPresent(icon, forKey: "icon")
        try c.encodeIfPresent(iconSvg, forKey: "icon_svg")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/notification_id", notificationId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/title", title, .init(maxLength: 500))
        ContractCheck.string(&v_, path + "/message", message, .init(maxLength: 5000))
