        ContractCheck.nested(&v_, path + "/popup_mode", popupMode)
        ContractCheck.number(&v_, path + "/priority", priority, minimum: 0, maximum: 100)
        ContractCheck.nested(&v_, path + "/color", color)
        ContractCheck.nested(&v_, path + "/action_type", actionType)
        ContractCheck.string(&v_, path + "/action_target", actionTarget, .init(maxLength: 2000))
        ContractCheck.nested(&v_, path + "/status", status)
        ContractCheck.string(&v_, path + "/icon_svg", iconSvg, .init(maxLength: 10000))
        return v_
