/// Per-client compliance status. sig only for restricting statuses; see
/// fixtures/crypto/compliance-vectors. need_token_update: device deactivated, guest past its
/// expiry, or the device's HA token changed after its last contact with the hub (ha_token_minted_at
/// > last_seen: rotated or remote access switched off while the device was away). The app stops
/// signing in to HA from outside until it is home again (HA IP ban). deleted: pending deletion.
/// Schema: `schemas/common/compliance-blob.json`.
public struct ComplianceBlob: ContractValue {
    public var status: ComplianceBlobStatus
    /// Unix seconds. The app does not check its age; a replayed signed status can only repeat a
    /// restricting status for the same device (docs/enforcement.md, Compliance status away from home).
    public var ts: Int
    public var sig: String?

    public init(
        status: ComplianceBlobStatus,
        ts: Int,
        sig: String? = nil
    ) {
        self.status = status
        self.ts = ts
        self.sig = sig
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        status = try c.decode(ComplianceBlobStatus.self, forKey: "status")
        ts = try c.decode(Int.self, forKey: "ts")
        sig = try c.decodeIfPresent(String.self, forKey: "sig")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(status, forKey: "status")
        try c.encode(ts, forKey: "ts")
        try c.encodeIfPresent(sig, forKey: "sig")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.nested(&v_, path + "/status", status)
        ContractCheck.string(&v_, path + "/sig", sig, .init(pattern: #"^[0-9a-f]{64}\z"#))
        var present_ = Set<String>()
        present_.insert("status")
        present_.insert("ts")
        if sig != nil { present_.insert("sig") }
        let c0_ = ["need_token_update", "deleted"].contains(status.rawValue)
        let c1_ = ["compliant", "unknown"].contains(status.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: [], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c1_, thenRequired: [], thenForbidden: ["sig"], elseRequired: [], elseForbidden: [])])
        return v_
    }
}

