/// onboard_ok.sealed: HPKE base mode (RFC 9180) DHKEM(X25519, HKDF-SHA256), HKDF-SHA256,
/// ChaCha20Poly1305, sequence number 0. Case rfc9180-a.2.1-seq0 is the RFC test vector A.2.1 (first
/// encryption); case onboard-v1 uses info "hub/onboard/v1", aad = session id (ASCII) and the
/// plaintext JSON {client_id, secret}; case watch-access-v1 uses info "hub/watch-access/v1", aad =
/// client_id (ASCII) and a sealed watch access (crypto/watch-access-plaintext.json,
/// watch_access.sealed). tools/validate.py recomputes enc and ct from sk_e and checks that sk_r
/// opens ct; the hub and the apps (CryptoKit HPKE.Recipient) open every case.
/// Schema: `schemas/crypto/onboard-seal-vectors.json`.
public struct CryptoOnboardSealVectors: ContractValue {
    public var suite: String
    public var kemId: Int
    public var kdfId: Int
    public var aeadId: Int
    public var mode: Int
    public var cases: [CryptoOnboardSealVectorsCasesItem]

    public init(
        suite: String,
        kemId: Int,
        kdfId: Int,
        aeadId: Int,
        mode: Int,
        cases: [CryptoOnboardSealVectorsCasesItem]
    ) {
        self.suite = suite
        self.kemId = kemId
        self.kdfId = kdfId
        self.aeadId = aeadId
        self.mode = mode
        self.cases = cases
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        suite = try c.decode(String.self, forKey: "suite")
        kemId = try c.decode(Int.self, forKey: "kem_id")
        kdfId = try c.decode(Int.self, forKey: "kdf_id")
        aeadId = try c.decode(Int.self, forKey: "aead_id")
        mode = try c.decode(Int.self, forKey: "mode")
        cases = try c.decode([CryptoOnboardSealVectorsCasesItem].self, forKey: "cases")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(suite, forKey: "suite")
        try c.encode(kemId, forKey: "kem_id")
        try c.encode(kdfId, forKey: "kdf_id")
        try c.encode(aeadId, forKey: "aead_id")
        try c.encode(mode, forKey: "mode")
        try c.encode(cases, forKey: "cases")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/suite", suite, const: "X25519-SHA256-ChaCha20Poly1305")
        ContractCheck.number(&v_, path + "/kem_id", kemId, const: 32)
        ContractCheck.number(&v_, path + "/kdf_id", kdfId, const: 1)
        ContractCheck.number(&v_, path + "/aead_id", aeadId, const: 3)
        ContractCheck.number(&v_, path + "/mode", mode, const: 0)
        ContractCheck.items(&v_, path + "/cases", cases, minItems: 2)
        ContractCheck.nested(&v_, path + "/cases", cases)
        return v_
    }
}

