        ContractCheck.number(&v_, path + "/version", version, minimum: 1)
        ContractCheck.nested(&v_, path + "/limits", limits)
        ContractCheck.items(&v_, path + "/forbidden_fields", forbiddenFields, minItems: 1, unique: true)
        for (i0_, x0_) in forbiddenFields.enumerated() {
