        ContractCheck.nested(&v_, path + "/enforcement", enforcement)
        ContractCheck.nested(&v_, path + "/enforcement_with_hub_path", enforcementWithHubPath)
        ContractCheck.nested(&v_, path + "/enforcement_with_checked_path", enforcementWithCheckedPath)
        ContractCheck.nested(&v_, path + "/watch_limit", watchLimit)
        return v_
    }
}

/// Safety entities: notifications about them are never suppressed; with parental controls they are
/// always visible read-only (controlling the alarm stays blocked); “When away” is at least view for
/// them. No delivery promise: no push, the app shows them while open; the product is no alarm
/// system.
public struct DataProfileRulesSafetyEntities: ContractValue {
    public var domains: [String]
    public var binarySensorDeviceClasses: [String]

    public init(
        domains: [String],
        binarySensorDeviceClasses: [String]
    ) {
        self.domains = domains
        self.binarySensorDeviceClasses = binarySensorDeviceClasses
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        domains = try c.decode([String].self, forKey: "domains")
        binarySensorDeviceClasses = try c.decode([String].self, forKey: "binary_sensor_device_classes")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(domains, forKey: "domains")
        try c.encode(binarySensorDeviceClasses, forKey: "binary_sensor_device_classes")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.items(&v_, path + "/domains", domains, unique: true)
        ContractCheck.items(&v_, path + "/binary_sensor_device_classes", binarySensorDeviceClasses, unique: true)
        return v_
    }
}

/// Catalog of the profile rules: one source for hub (resolver, validation, migration), admin UI
/// (editor, texts) and apps (labels, reason sentences). Semantics: docs/profiles.md.
/// tools/validate.py checks the catalog against schemas/common/profile-rule-values.json and
/// $defs/profile_rule_key, and every resolver vector in fixtures/profiles/resolve against the
/// reference resolver tools/profiles_ref.py.
/// Schema: `schemas/data/profile-rules.json`.
public struct DataProfileRules: ContractValue {
    public var catalogVersion: Int
    public var groups: [DataProfileRulesGroupsItem]
    public var rules: [DataProfileRulesRulesItem]
    public var boundaries: [DataProfileRulesBoundariesItem]
    /// The profile kinds ($defs/profile_kind) in display order, with labels, an icon and the platforms
    /// a device of this kind can have when it is set up (onboard_info.grant offers only kinds that fit
    /// the waiting device). guest_access = devices of this kind are set up as guest access with an
    /// expiry (guest, house sitter, babysitter). Watches have no kind of their own: a phone sets up its
    /// own watch with the watch's default profile.
    public var profileKinds: [DataProfileRulesProfileKindsItem]
    public var reasons: [DataProfileRulesReasonsItem]
    public var expiryPresets: [DataProfileRulesExpiryPresetsItem]
    /// Labels of the enforcement kinds for admin UI and apps (honest display).
    public var enforcement: [DataProfileRulesEnforcementItem]
    /// A temporary device adjustment ends at least min_minutes and at most max_days in the future (else
    /// 422 override.expires_at).
    public var expiryLimits: DataProfileRulesExpiryLimits
    /// Priority thresholds (notification priority 0-100) of the rule notification_level: important from
    /// important_min_priority, critical from critical_min_priority (never suppressed).
    public var notifications: DataProfileRulesNotifications
    /// Safety entities: notifications about them are never suppressed; with parental controls they are
    /// always visible read-only (controlling the alarm stays blocked); “When away” is at least view for
    /// them. No delivery promise: no push, the app shows them while open; the product is no alarm
    /// system.
    public var safetyEntities: DataProfileRulesSafetyEntities
    public var guestAccess: DataProfileRulesGuestAccess
    public var limits: DataProfileRulesLimits

    public init(
        catalogVersion: Int,
        groups: [DataProfileRulesGroupsItem],
        rules: [DataProfileRulesRulesItem],
        boundaries: [DataProfileRulesBoundariesItem],
        profileKinds: [DataProfileRulesProfileKindsItem],
        reasons: [DataProfileRulesReasonsItem],
        expiryPresets: [DataProfileRulesExpiryPresetsItem],
        enforcement: [DataProfileRulesEnforcementItem],
        expiryLimits: DataProfileRulesExpiryLimits,
        notifications: DataProfileRulesNotifications,
        safetyEntities: DataProfileRulesSafetyEntities,
        guestAccess: DataProfileRulesGuestAccess,
        limits: DataProfileRulesLimits
    ) {
        self.catalogVersion = catalogVersion
        self.groups = groups
        self.rules = rules
        self.boundaries = boundaries
        self.profileKinds = profileKinds
        self.reasons = reasons
        self.expiryPresets = expiryPresets
        self.enforcement = enforcement
        self.expiryLimits = expiryLimits
        self.notifications = notifications
        self.safetyEntities = safetyEntities
        self.guestAccess = guestAccess
        self.limits = limits
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        catalogVersion = try c.decode(Int.self, forKey: "catalog_version")
        groups = try c.decode([DataProfileRulesGroupsItem].self, forKey: "groups")
        rules = try c.decode([DataProfileRulesRulesItem].self, forKey: "rules")
        boundaries = try c.decode([DataProfileRulesBoundariesItem].self, forKey: "boundaries")
        profileKinds = try c.decode([DataProfileRulesProfileKindsItem].self, forKey: "profile_kinds")
        reasons = try c.decode([DataProfileRulesReasonsItem].self, forKey: "reasons")
        expiryPresets = try c.decode([DataProfileRulesExpiryPresetsItem].self, forKey: "expiry_presets")
        enforcement = try c.decode([DataProfileRulesEnforcementItem].self, forKey: "enforcement")
        expiryLimits = try c.decode(DataProfileRulesExpiryLimits.self, forKey: "expiry_limits")
        notifications = try c.decode(DataProfileRulesNotifications.self, forKey: "notifications")
        safetyEntities = try c.decode(DataProfileRulesSafetyEntities.self, forKey: "safety_entities")
        guestAccess = try c.decode(DataProfileRulesGuestAccess.self, forKey: "guest_access")
        limits = try c.decode(DataProfileRulesLimits.self, forKey: "limits")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(catalogVersion, forKey: "catalog_version")
        try c.encode(groups, forKey: "groups")
        try c.encode(rules, forKey: "rules")
        try c.encode(boundaries, forKey: "boundaries")
        try c.encode(profileKinds, forKey: "profile_kinds")
        try c.encode(reasons, forKey: "reasons")
        try c.encode(expiryPresets, forKey: "expiry_presets")
        try c.encode(enforcement, forKey: "enforcement")
        try c.encode(expiryLimits, forKey: "expiry_limits")
        try c.encode(notifications, forKey: "notifications")
        try c.encode(safetyEntities, forKey: "safety_entities")
        try c.encode(guestAccess, forKey: "guest_access")
        try c.encode(limits, forKey: "limits")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.number(&v_, path + "/catalog_version", catalogVersion, minimum: 1)
        ContractCheck.nested(&v_, path + "/groups", groups)
        ContractCheck.items(&v_, path + "/rules", rules, minItems: 1)
        ContractCheck.nested(&v_, path + "/rules", rules)
        ContractCheck.nested(&v_, path + "/boundaries", boundaries)
