    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        catalogVersion = try c.decode(Int.self, forKey: "catalog_version")
        suggestions = try c.decode([DataProfileSuggestionsSuggestionsItem].self, forKey: "suggestions")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(catalogVersion, forKey: "catalog_version")
        try c.encode(suggestions, forKey: "suggestions")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.number(&v_, path + "/catalog_version", catalogVersion, minimum: 1)
        ContractCheck.items(&v_, path + "/suggestions", suggestions, minItems: 1)
        ContractCheck.nested(&v_, path + "/suggestions", suggestions)
        return v_
    }
}

