        ContractCheck.string(&v_, path + "/action", action, .init(pattern: #"^[a-z_]{1,64}\z"#))
        ContractCheck.nested(&v_, path + "/route", route)
        ContractCheck.nested(&v_, path + "/origin", origin)
        ContractCheck.nested(&v_, path + "/reason", reason)
        ContractCheck.number(&v_, path + "/count", count, minimum: 1, maximum: 100000)
        ContractCheck.nested(&v_, path + "/ha_group", haGroup)
        ContractCheck.string(&v_, path + "/rules_hash", rulesHash, .init(pattern: #"^[0-9a-f]{64}\z"#))
        ContractCheck.nested(&v_, path + "/reliability", reliability)
        ContractCheck.string(&v_, path + "/version", version, .init(maxLength: 32))
        var present_ = Set<String>()
        present_.insert("id")
        present_.insert("type")
        present_.insert("at")
        if clientId != nil { present_.insert("client_id") }
        if haUserId != nil { present_.insert("ha_user_id") }
        if entityId != nil { present_.insert("entity_id") }
        if action != nil { present_.insert("action") }
        if route != nil { present_.insert("route") }
        if origin != nil { present_.insert("origin") }
        if reason != nil { present_.insert("reason") }
        if count != nil { present_.insert("count") }
        if since != nil { present_.insert("since") }
        if haGroup != nil { present_.insert("ha_group") }
        if rulesHash != nil { present_.insert("rules_hash") }
        if reliability != nil { present_.insert("reliability") }
        if version != nil { present_.insert("version") }
        let c0_ = ["control", "denied"].contains(type.rawValue)
        let c1_ = ["denied"].contains(type.rawValue)
        let c2_ = ["access_group_restored", "direct_access_attempt", "rules_applied"].contains(type.rawValue)
        let c3_ = ["integration_outage"].contains(type.rawValue)
