        id = try c.decode(String.self, forKey: "id")
        at = try c.decode(String.self, forKey: "at")
        clientId = try c.decode(String.self, forKey: "client_id")
        childName = try c.decodeIfPresent(String.self, forKey: "child_name")
        kind = try c.decode(FamilyActivityKind.self, forKey: "kind")
        entityId = try c.decodeIfPresent(String.self, forKey: "entity_id")
        entityName = try c.decodeIfPresent(String.self, forKey: "entity_name")
        action = try c.decodeIfPresent(String.self, forKey: "action")
        reason = try c.decodeIfPresent(RuleBlockedReason.self, forKey: "reason")
        rule = try c.decodeIfPresent(ProfileRuleKey.self, forKey: "rule")
        requestId = try c.decodeIfPresent(String.self, forKey: "request_id")
        until = try c.decodeIfPresent(String.self, forKey: "until")
        count = try c.decodeIfPresent(Int.self, forKey: "count")
        by = try c.decodeIfPresent(FamilyActor.self, forKey: "by")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(id, forKey: "id")
        try c.encode(at, forKey: "at")
        try c.encode(clientId, forKey: "client_id")
        try c.encodeIfPresent(childName, forKey: "child_name")
        try c.encode(kind, forKey: "kind")
        try c.encodeIfPresent(entityId, forKey: "entity_id")
        try c.encodeIfPresent(entityName, forKey: "entity_name")
        try c.encodeIfPresent(action, forKey: "action")
        try c.encodeIfPresent(reason, forKey: "reason")
        try c.encodeIfPresent(rule, forKey: "rule")
        try c.encodeIfPresent(requestId, forKey: "request_id")
        try c.encodeIfPresent(until, forKey: "until")
        try c.encodeIfPresent(count, forKey: "count")
        try c.encodeIfPresent(by, forKey: "by")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/id", id, .init(maxLength: 64))
        ContractCheck.string(&v_, path + "/client_id", clientId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/child_name", childName, .init(maxLength: 100))
        ContractCheck.nested(&v_, path + "/kind", kind)
        ContractCheck.string(&v_, path + "/entity_id", entityId, .init(pattern: #"^[a-z0-9_]+\.[a-z0-9_]+\z"#, maxLength: 255))
        ContractCheck.string(&v_, path + "/entity_name", entityName, .init(maxLength: 255))
        ContractCheck.string(&v_, path + "/action", action, .init(pattern: #"^[a-z_]{1,64}\z"#))
        ContractCheck.nested(&v_, path + "/reason", reason)
        ContractCheck.nested(&v_, path + "/rule", rule)
        ContractCheck.string(&v_, path + "/request_id", requestId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.number(&v_, path + "/count", count, minimum: 1)
        ContractCheck.nested(&v_, path + "/by", by)
        return v_
    }
}

