/// Unauthenticated, 1 request/s per IP. Either the neutral body {v:1, status:'unknown', ts:<now>}
/// (unknown client, unsigned status, toggle off) or a signed restricting status relayed verbatim
/// from the hub. 'compliant' is never exposed (indistinguishable from unknown by design). The
/// iPhone and iPad app verifies sig (fixtures/crypto/compliance-vectors), not the age of ts; the
/// Android apps do not poll this view.
/// Schema: `schemas/integration/compliance-view.response.json`.
public struct IntegrationComplianceViewResponse: ContractValue {
    public var v: Int
    public var status: IntegrationComplianceViewResponseStatus
    public var ts: Int
    public var sig: String?

    public init(
        v: Int,
        status: IntegrationComplianceViewResponseStatus,
        ts: Int,
        sig: String? = nil
    ) {
        self.v = v
        self.status = status
        self.ts = ts
        self.sig = sig
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        v = try c.decode(Int.self, forKey: "v")
        status = try c.decode(IntegrationComplianceViewResponseStatus.self, forKey: "status")
        ts = try c.decode(Int.self, forKey: "ts")
        sig = try c.decodeIfPresent(String.self, forKey: "sig")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(v, forKey: "v")
        try c.encode(status, forKey: "status")
        try c.encode(ts, forKey: "ts")
        try c.encodeIfPresent(sig, forKey: "sig")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.number(&v_, path + "/v", v, const: 1)
        ContractCheck.nested(&v_, path + "/status", status)
        ContractCheck.string(&v_, path + "/sig", sig, .init(pattern: #"^[0-9a-f]{64}\z"#))
        var present_ = Set<String>()
        present_.insert("v")
        present_.insert("status")
        present_.insert("ts")
        if sig != nil { present_.insert("sig") }
        let c0_ = ["unknown"].contains(status.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: [], thenForbidden: ["sig"], elseRequired: ["sig"], elseForbidden: [])])
        return v_
    }
}

