/// Asks the integration to make sure the device has its own HA user with exactly one long-lived
/// access token and to deliver that token via POST /api/integration/client-token. Sent as WS push
/// provision_client and repeated in GET /api/integration/status provisioning[] until the hub has
/// the token. Handling MUST be idempotent: token_action=ensure reuses the device's existing token
/// (a new access token is derived from the same refresh token, refresh_token_id stays the same);
/// only token_action=rotate mints a new one.
/// Schema: `schemas/common/provision-request.json`.
public struct ProvisionRequest: ContractValue {
    public var clientId: String
    public var displayName: String
    public var ownerLabel: String?
    public var isGuest: Bool
    /// Device may use HA from outside the local network: the effective profile rule remote_access.
    /// Default false (local-first); also for guests when their profile allows it and for devices with
    /// parental controls (read-only key, docs/enforcement.md §7).
    public var remoteAllowed: Bool
    /// Guest expiry (UTC). The integration bounds the HA-side token lifetime to expiry + 7 days grace
    /// and rotates the token when an extension is no longer covered.
    public var guestExpiresAt: String?
    /// Correlation id for logs; not used for deduplication.
    public var requestId: String?
    /// ensure: create user/token if missing, otherwise re-deliver the current token. rotate: mint a new
    /// token for the same user; the integration removes the old one only after the hub acknowledged the
    /// new one.
    public var tokenAction: ProvisionRequestTokenAction
    /// Why the hub asks (logging, UI). pair = newly paired device (status pending); retry = earlier
    /// request unanswered; rotate = admin rotate-token; guest_extend = guest extended beyond the token
    /// lifetime; reprovision = the hub has no usable token for an active device (e.g. restored backup).
    public var reason: ProvisionRequestReason

    public init(
        clientId: String,
        displayName: String,
        ownerLabel: String? = nil,
        isGuest: Bool,
        remoteAllowed: Bool,
        guestExpiresAt: String? = nil,
        requestId: String? = nil,
        tokenAction: ProvisionRequestTokenAction,
        reason: ProvisionRequestReason
    ) {
        self.clientId = clientId
        self.displayName = displayName
        self.ownerLabel = ownerLabel
        self.isGuest = isGuest
        self.remoteAllowed = remoteAllowed
        self.guestExpiresAt = guestExpiresAt
        self.requestId = requestId
        self.tokenAction = tokenAction
        self.reason = reason
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        clientId = try c.decode(String.self, forKey: "client_id")
        displayName = try c.decode(String.self, forKey: "display_name")
        ownerLabel = try c.decodeIfPresent(String.self, forKey: "owner_label")
        isGuest = try c.decode(Bool.self, forKey: "is_guest")
        remoteAllowed = try c.decode(Bool.self, forKey: "remote_allowed")
        guestExpiresAt = try c.decodeIfPresent(String.self, forKey: "guest_expires_at")
        requestId = try c.decodeIfPresent(String.self, forKey: "request_id")
        tokenAction = try c.decode(ProvisionRequestTokenAction.self, forKey: "token_action")
        reason = try c.decode(ProvisionRequestReason.self, forKey: "reason")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(clientId, forKey: "client_id")
        try c.encode(displayName, forKey: "display_name")
        try c.encodeIfPresent(ownerLabel, forKey: "owner_label")
        try c.encode(isGuest, forKey: "is_guest")
        try c.encode(remoteAllowed, forKey: "remote_allowed")
        try c.encodeIfPresent(guestExpiresAt, forKey: "guest_expires_at")
        try c.encodeIfPresent(requestId, forKey: "request_id")
        try c.encode(tokenAction, forKey: "token_action")
        try c.encode(reason, forKey: "reason")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/client_id", clientId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/display_name", displayName, .init(minLength: 1, maxLength: 100))
        ContractCheck.string(&v_, path + "/owner_label", ownerLabel, .init(maxLength: 50))
        ContractCheck.string(&v_, path + "/guest_expires_at", guestExpiresAt, .init(format: "date-time"))
        ContractCheck.string(&v_, path + "/request_id", requestId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.nested(&v_, path + "/token_action", tokenAction)
        ContractCheck.nested(&v_, path + "/reason", reason)
        var present_ = Set<String>()
        present_.insert("client_id")
        present_.insert("display_name")
        if ownerLabel != nil { present_.insert("owner_label") }
        present_.insert("is_guest")
        present_.insert("remote_allowed")
        if guestExpiresAt != nil { present_.insert("guest_expires_at") }
        if requestId != nil { present_.insert("request_id") }
        present_.insert("token_action")
        present_.insert("reason")
        let c0_ = [true].contains(isGuest)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: ["guest_expires_at", "guest_expires_at"], thenForbidden: [], elseRequired: [], elseForbidden: [])])
        return v_
    }
}

