    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(version, forKey: "version")
        try c.encode(instanceId, forKey: "instance_id")
        try c.encode(connectedClients, forKey: "connected_clients")
        try c.encode(wsPush, forKey: "ws_push")
        try c.encodeIfPresent(protocolVersion, forKey: "protocol_version")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/instance_id", instanceId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.bool(&v_, path + "/ws_push", wsPush, const: true)
        return v_
    }
}

