/// Full snapshot for the HA integration (poll 30 s, 300 s with WS push). Contains names and GPS
/// positions. Per-device users: per-client ha_user_id/ha_token_status/owner_label/remote_allowed
/// and the provisioning[] backlog; no owner token any more. ha_user_holds: HA users kept until a
/// deleted device confirmed its reset.
/// Schema: `schemas/integration/status.response.json`.
public struct IntegrationStatusResponse: ContractValue {
    public var hub: IntegrationStatusResponseHub
    public var areas: [IntegrationStatusResponseAreasItem]
    public var clients: [IntegrationStatusResponseClientsItem]
    public var guests: [IntegrationStatusResponseGuestsItem]
    public var guestCount: Int
    public var pairingActive: Bool
    public var pairingRemaining: Int
    public var pairingIsGuest: Bool
    public var pairingGuestExpiresAt: String?
    /// Hub option pairing_qr_camera: when GET /api/integration/pairing-qr returns the QR code with the
    /// PIN (X-Pairing-Pin: included). off = never, guests = only during a guest pairing window
    /// (X-Pairing-Kind: guest), all = during every window. The integration shows an included image only
    /// when this mode allows its X-Pairing-Kind. Missing = off.
    public var pairingQrCamera: IntegrationStatusResponsePairingQrCamera?
    public var allowPairingViaIntegration: Bool
    public var complianceEndpointEnabled: Bool
    public var tombstones: [IntegrationStatusResponseTombstonesItem]
    public var areaCount: Int
    public var clientCount: Int
    /// Outstanding provisioning requests (same shape as provision_client.data): every active client
    /// with ha_token_status=pending (reason pair/reprovision) and rotations not yet answered (reason
    /// rotate/guest_extend). Fallback for a missed WS push; the integration handles each item exactly
    /// like a provision_client message. Empty = nothing to do.
    public var provisioning: [ProvisionRequest]
    /// Deleted devices whose HA user stays until the app confirmed its reset (client_reset_ack) or the
    /// grace period ran out (24 h offline); hidden tombstones included. The integration must not remove
    /// the HA user of a listed client id on its own (reconcile skips it); the hub sends
    /// deprovision_client when it releases the hold. Empty = no holds.
    public var haUserHolds: [String]
    /// Rule snapshots for the integration action <ns>.control. Missing = the hub does not deliver
    /// snapshots (the integration keeps the ones it has).
    public var enforcement: IntegrationStatusResponseEnforcement?

    public init(
        hub: IntegrationStatusResponseHub,
        areas: [IntegrationStatusResponseAreasItem],
        clients: [IntegrationStatusResponseClientsItem],
        guests: [IntegrationStatusResponseGuestsItem],
        guestCount: Int,
        pairingActive: Bool,
        pairingRemaining: Int,
        pairingIsGuest: Bool,
        pairingGuestExpiresAt: String? = nil,
        pairingQrCamera: IntegrationStatusResponsePairingQrCamera? = nil,
        allowPairingViaIntegration: Bool,
        complianceEndpointEnabled: Bool,
        tombstones: [IntegrationStatusResponseTombstonesItem],
        areaCount: Int,
        clientCount: Int,
        provisioning: [ProvisionRequest],
        haUserHolds: [String],
        enforcement: IntegrationStatusResponseEnforcement? = nil
    ) {
        self.hub = hub
        self.areas = areas
        self.clients = clients
        self.guests = guests
        self.guestCount = guestCount
        self.pairingActive = pairingActive
        self.pairingRemaining = pairingRemaining
        self.pairingIsGuest = pairingIsGuest
        self.pairingGuestExpiresAt = pairingGuestExpiresAt
        self.pairingQrCamera = pairingQrCamera
        self.allowPairingViaIntegration = allowPairingViaIntegration
        self.complianceEndpointEnabled = complianceEndpointEnabled
        self.tombstones = tombstones
        self.areaCount = areaCount
        self.clientCount = clientCount
        self.provisioning = provisioning
        self.haUserHolds = haUserHolds
        self.enforcement = enforcement
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        hub = try c.decode(IntegrationStatusResponseHub.self, forKey: "hub")
        areas = try c.decode([IntegrationStatusResponseAreasItem].self, forKey: "areas")
        clients = try c.decode([IntegrationStatusResponseClientsItem].self, forKey: "clients")
        guests = try c.decode([IntegrationStatusResponseGuestsItem].self, forKey: "guests")
