/// Control a wall panel or TV, triggered by POST /api/integration/clients/{id}/panel (Home
/// Assistant entity or action, only HA admins and automations) or POST
/// /api/pairing/clients/{id}/panel (admin UI test buttons). The hub has already checked platform,
/// wall panel mode, guest boundary and the rule panel_remote. The app executes it and answers
/// within 5 s with panel_command_ok (incl. the new panel status) or panel_command_error; without an
/// answer the hub reports timeout. Pro is checked by the app (not_pro).
/// Schema: `schemas/ws/command/panel_command.json`.
public struct PanelCommand: ContractValue {
    public static let type = "command"
    public static let command = "panel_command"
    public var id: String
    public var action: PanelAction
    /// set_brightness only: backlight 0.05–1 (Home Assistant number 5–100 %).
    public var level: Double?
    /// set_brightness_mode only.
    public var mode: PanelBrightnessMode?
    /// announce only: text to speak and show (never logged).
    public var text: String?
    /// announce only: volume in percent; capped by panel_announce.volume_max (missing = volume_max).
    public var volume: Int?
    /// announce only: chime before the text (missing = true).
    public var chime: Bool?
    /// show_camera only: the camera to open.
    public var entityId: String?

    public init(
        id: String,
        action: PanelAction,
        level: Double? = nil,
        mode: PanelBrightnessMode? = nil,
        text: String? = nil,
        volume: Int? = nil,
        chime: Bool? = nil,
        entityId: String? = nil
    ) {
        self.id = id
        self.action = action
        self.level = level
        self.mode = mode
        self.text = text
        self.volume = volume
        self.chime = chime
        self.entityId = entityId
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        try c.expectConstant(Self.command, forKey: "command")
        id = try c.decode(String.self, forKey: "id")
        action = try c.decode(PanelAction.self, forKey: "action")
        level = try c.decodeIfPresent(Double.self, forKey: "level")
        mode = try c.decodeIfPresent(PanelBrightnessMode.self, forKey: "mode")
        text = try c.decodeIfPresent(String.self, forKey: "text")
        volume = try c.decodeIfPresent(Int.self, forKey: "volume")
        chime = try c.decodeIfPresent(Bool.self, forKey: "chime")
        entityId = try c.decodeIfPresent(String.self, forKey: "entity_id")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(Self.command, forKey: "command")
        try c.encode(id, forKey: "id")
        try c.encode(action, forKey: "action")
        try c.encodeIfPresent(level, forKey: "level")
        try c.encodeIfPresent(mode, forKey: "mode")
        try c.encodeIfPresent(text, forKey: "text")
        try c.encodeIfPresent(volume, forKey: "volume")
        try c.encodeIfPresent(chime, forKey: "chime")
        try c.encodeIfPresent(entityId, forKey: "entity_id")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/id", id, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.nested(&v_, path + "/action", action)
        ContractCheck.finite(&v_, path + "/level", level)
        ContractCheck.number(&v_, path + "/level", level, minimum: 0.05, maximum: 1.0)
        ContractCheck.nested(&v_, path + "/mode", mode)
        ContractCheck.string(&v_, path + "/text", text, .init(minLength: 1, maxLength: 300))
        ContractCheck.number(&v_, path + "/volume", volume, minimum: 0, maximum: 100)
        ContractCheck.string(&v_, path + "/entity_id", entityId, .init(pattern: #"^camera\.[a-z0-9_]+\z"#, maxLength: 255))
        var present_ = Set<String>()
        present_.insert("id")
        present_.insert("action")
        if level != nil { present_.insert("level") }
        if mode != nil { present_.insert("mode") }
        if text != nil { present_.insert("text") }
        if volume != nil { present_.insert("volume") }
        if chime != nil { present_.insert("chime") }
        if entityId != nil { present_.insert("entity_id") }
        let c0_ = ["set_brightness"].contains(action.rawValue)
        let c1_ = ["set_brightness_mode"].contains(action.rawValue)
        let c2_ = ["announce"].contains(action.rawValue)
        let c3_ = ["show_camera"].contains(action.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: ["level"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c1_, thenRequired: ["mode"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c2_, thenRequired: ["text"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c3_, thenRequired: ["entity_id"], thenForbidden: [], elseRequired: [], elseForbidden: [])])
        return v_
    }
}

