/// Values a setting-up device may hand out compared with its own effective values (docs/setup.md,
/// No escalation). cases: an ordered rule along its order (tools/profiles_ref.py looser).
/// key_cases: control_path by key level after the platform mapping, none < read_only < full
/// (key_looser): new and mine are effective control_path and remote_access values. looser = not
/// offered. tools/validate.py recomputes every case.
/// Schema: `schemas/profiles/no-escalation.json`.
public struct ProfilesNoEscalation: ContractValue {
    public var description: String
    public var cases: [ProfilesNoEscalationCasesItem]?
    public var keyCases: [ProfilesNoEscalationKeyCasesItem]?

    public init(
        description: String,
        cases: [ProfilesNoEscalationCasesItem]? = nil,
        keyCases: [ProfilesNoEscalationKeyCasesItem]? = nil
    ) {
        self.description = description
        self.cases = cases
        self.keyCases = keyCases
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        description = try c.decode(String.self, forKey: "description")
        cases = try c.decodeIfPresent([ProfilesNoEscalationCasesItem].self, forKey: "cases")
        keyCases = try c.decodeIfPresent([ProfilesNoEscalationKeyCasesItem].self, forKey: "key_cases")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(description, forKey: "description")
        try c.encodeIfPresent(cases, forKey: "cases")
        try c.encodeIfPresent(keyCases, forKey: "key_cases")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.items(&v_, path + "/cases", cases, minItems: 1)
        ContractCheck.nested(&v_, path + "/cases", cases)
        ContractCheck.items(&v_, path + "/key_cases", keyCases, minItems: 1)
        ContractCheck.nested(&v_, path + "/key_cases", keyCases)
        var present_ = Set<String>()
        present_.insert("description")
        if cases != nil { present_.insert("cases") }
        if keyCases != nil { present_.insert("key_cases") }
        ContractCheck.object(&v_, path, present: present_, anyOfRequired: [["cases"], ["key_cases"]])
        return v_
    }
}

