        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        answer = try c.decode(FamilyAnswer.self, forKey: "answer")
        duration = try c.decodeIfPresent(AccessRequestDuration.self, forKey: "duration")
        message = try c.decodeIfPresent(AccessDeclineMessage.self, forKey: "message")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(answer, forKey: "answer")
        try c.encodeIfPresent(duration, forKey: "duration")
        try c.encodeIfPresent(message, forKey: "message")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.nested(&v_, path + "/answer", answer)
        ContractCheck.nested(&v_, path + "/duration", duration)
        ContractCheck.nested(&v_, path + "/message", message)
        var present_ = Set<String>()
        present_.insert("answer")
        if duration != nil { present_.insert("duration") }
        if message != nil { present_.insert("message") }
        let c0_ = ["yes"].contains(answer.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: ["duration"], thenForbidden: [], elseRequired: [], elseForbidden: [])])
        return v_
    }
}

