        present_.insert("action")
        if profileId != nil { present_.insert("profile_id") }
        if discardOverrides != nil { present_.insert("discard_overrides") }
        if areaId != nil { present_.insert("area_id") }
        if rule != nil { present_.insert("rule") }
        if value != nil { present_.insert("value") }
        if expires != nil { present_.insert("expires") }
        if expiresAt != nil { present_.insert("expires_at") }
        if note != nil { present_.insert("note") }
        if dryRun != nil { present_.insert("dry_run") }
        let c0_ = ["assign_profile"].contains(action.rawValue)
        let c1_ = ["set_own_area"].contains(action.rawValue)
        let c2_ = ["set_override"].contains(action.rawValue)
        let c3_ = ["remove_override"].contains(action.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: ["profile_id"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c1_, thenRequired: ["area_id"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c2_, thenRequired: ["rule", "value"], thenForbidden: [], elseRequired: [], elseForbidden: []), (matched: c3_, thenRequired: ["rule"], thenForbidden: [], elseRequired: [], elseForbidden: [])])
        return v_
    }
