/// Answer of every profile, assignment, adjustment, own-area, default-profile and bulk write with
/// ?dry_run=true (preview before saving): nothing is saved; per affected device the effective
/// values before and after (resolver), the adjustments that would be deleted and the consequences
/// for the HA key and remote access. Without dry_run the same write saves and answers with its
/// normal body; the audit entry contains before/after. Remote PINs (profile or device) never appear
/// in a preview, a diff or the audit.
/// Schema: `schemas/rest/profile-preview.response.json`.
public struct RestProfilePreviewResponse: ContractValue {
    public var dryRun: Bool
    public var affectedCount: Int
    /// Rules loosened on at least one device (confirmation needed).
    public var loosenedRules: [ProfileRuleKey]
    /// Devices the change leaves unchanged may be listed when the change alters their pair
    /// (hub_remote_now, hub_remote_at), both computed before and after the change at the same moment;
    /// such an entry has changes [], overrides_removed [], ha_key and remote_access unchanged, and does
    /// not count in affected_count.
    public var devices: [RestProfilePreviewResponseDevicesItem]
    /// PATCH /api/profiles/{profile_id}?dry_run=true only: the scene hints of the draft
    /// (rest/profile.json scene_hints), as they would be after saving.
    public var sceneHints: [SceneHint]?
    /// Watches the write removes: a child's watch whose phone may no longer have one. Missing = none.
    /// An adult's watch is never removed by a write; it follows its phone (limited_by_phone).
    public var watchesRemoved: [RestProfilePreviewResponseWatchesRemovedItem]?

    public init(
        dryRun: Bool,
        affectedCount: Int,
        loosenedRules: [ProfileRuleKey],
        devices: [RestProfilePreviewResponseDevicesItem],
        sceneHints: [SceneHint]? = nil,
        watchesRemoved: [RestProfilePreviewResponseWatchesRemovedItem]? = nil
    ) {
        self.dryRun = dryRun
        self.affectedCount = affectedCount
        self.loosenedRules = loosenedRules
        self.devices = devices
        self.sceneHints = sceneHints
        self.watchesRemoved = watchesRemoved
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        dryRun = try c.decode(Bool.self, forKey: "dry_run")
        affectedCount = try c.decode(Int.self, forKey: "affected_count")
        loosenedRules = try c.decode([ProfileRuleKey].self, forKey: "loosened_rules")
        devices = try c.decode([RestProfilePreviewResponseDevicesItem].self, forKey: "devices")
        sceneHints = try c.decodeIfPresent([SceneHint].self, forKey: "scene_hints")
        watchesRemoved = try c.decodeIfPresent([RestProfilePreviewResponseWatchesRemovedItem].self, forKey: "watches_removed")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(dryRun, forKey: "dry_run")
        try c.encode(affectedCount, forKey: "affected_count")
        try c.encode(loosenedRules, forKey: "loosened_rules")
        try c.encode(devices, forKey: "devices")
        try c.encodeIfPresent(sceneHints, forKey: "scene_hints")
        try c.encodeIfPresent(watchesRemoved, forKey: "watches_removed")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.bool(&v_, path + "/dry_run", dryRun, const: true)
        ContractCheck.number(&v_, path + "/affected_count", affectedCount, minimum: 0)
        ContractCheck.items(&v_, path + "/loosened_rules", loosenedRules, unique: true)
        ContractCheck.nested(&v_, path + "/loosened_rules", loosenedRules)
        ContractCheck.nested(&v_, path + "/devices", devices)
        ContractCheck.items(&v_, path + "/scene_hints", sceneHints, maxItems: 50)
        ContractCheck.nested(&v_, path + "/scene_hints", sceneHints)
        ContractCheck.items(&v_, path + "/watches_removed", watchesRemoved, maxItems: 500)
        ContractCheck.nested(&v_, path + "/watches_removed", watchesRemoved)
        return v_
    }
}

