    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        retentionDays = try c.decode(Int.self, forKey: "retention_days")
        quietDefault = try c.decodeIfPresent(RestEventNotificationsQuietDefault.self, forKey: "quiet_default")
        rules = try c.decode([RestEventNotificationsRulesItem].self, forKey: "rules")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(retentionDays, forKey: "retention_days")
        try c.encodeIfPresent(quietDefault, forKey: "quiet_default")
        try c.encode(rules, forKey: "rules")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.number(&v_, path + "/retention_days", retentionDays, minimum: 7, maximum: 90)
        ContractCheck.nested(&v_, path + "/quiet_default", quietDefault)
