        ContractCheck.string(&v_, path + "/profile_id", profileId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/own_area_id", ownAreaId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/owner_label", ownerLabel, .init(maxLength: 50))
        ContractCheck.number(&v_, path + "/guest_hours", guestHours, minimum: 1, maximum: 2160)
        var present_ = Set<String>()
