/// A profile: GET /api/profiles/{profile_id}, answer of every profile write. One profile per
/// device; profiles are created freely by the admin (max limits.max_profiles), from a suggestion,
/// from a device or empty.
/// Schema: `schemas/rest/profile.json`.
public struct RestProfile: ContractValue {
    public var id: String
    public var name: String
    /// Kind of the profile: groups profiles for “Set up new devices” (rule setup_devices) and the
    /// gallery; independent of child_protection. Only kind person may have setup_devices (other kinds
    /// resolve it to not_applicable, reason requires_profile_kind).
    public var kind: ProfileKind
    /// One sentence for the profile card.
    public var description: String?
    public var icon: String?
    public var color: String?
    /// Parental controls. Not for a profile with guest devices (422 profile.guest_child_protection).
    public var childProtection: Bool
    /// Answers: every rule of the catalog (defaults filled in, see catalog_defaults).
    public var rules: ProfileRuleValues
    /// Rules with checkbox “Fixed”: no device adjustment possible. Always contains the rules without
    /// checkbox.
    public var fixed: [ProfileRuleKey]
    /// Rules where the person at the device decides (value = starting value).
    public var userChoice: [ProfileRuleKey]
    /// Suggestion the profile was copied from (information only; a later suggestion version never
    /// changes the profile).
    public var origin: RestProfileOrigin?
    /// A newer version of the origin suggestion exists (POST
    /// /api/profiles/{profile_id}/apply-suggestion, only on request).
    public var suggestionUpdate: RestProfileSuggestionUpdate?
    /// Rules the profile does not contain yet (added by a hub update); they use the catalog default
    /// until the profile is saved.
    public var catalogDefaults: [ProfileRuleKey]
    /// Device types this profile is the default profile of.
    public var defaultFor: [DefaultProfileSlot]
    public var deviceCount: Int
    /// Devices with at least one adjustment.
    public var adjustedDeviceCount: Int
    public var guestDeviceCount: Int
    public var rev: Int
    public var createdAt: String
    public var updatedAt: String
    public var updatedBy: String?
    /// The profile has its own remote PIN for “settings with remote PIN”: valid for every device of the
    /// profile; a device PIN wins unless remote_pin_fixed. Never returned, only this flag.
    public var hasRemotePin: Bool
    /// Checkbox “Fixed” of the profile PIN: device PINs are ignored and PUT …/remote-pin answers 422
    /// remote_pin.fixed.
    public var remotePinFixed: Bool
    /// Released scenes and scripts with targets this profile may not switch (docs/enforcement.md §2
    /// step 4), computed for the profile without a device (no own area, no adjustments). Only in GET
    /// and PATCH /api/profiles/{profile_id}; empty when Home Assistant is not reachable. At most 50.
    public var sceneHints: [SceneHint]?
    /// Per access (member, guest) and platform: whether a device paired with this profile now would be
    /// Hub only with remote access (it would hold the read-only key because of remote access; a new
    /// device has no adjustment). Always false on tvos, android_tv, watchos and wearos. Missing on
    /// older hubs.
    public var hubRemotePairing: RestProfileHubRemotePairing?

    public init(
        id: String,
        name: String,
        kind: ProfileKind,
        description: String?,
        icon: String?,
        color: String?,
        childProtection: Bool,
        rules: ProfileRuleValues,
        fixed: [ProfileRuleKey],
        userChoice: [ProfileRuleKey],
        origin: RestProfileOrigin?,
        suggestionUpdate: RestProfileSuggestionUpdate?,
        catalogDefaults: [ProfileRuleKey],
        defaultFor: [DefaultProfileSlot],
        deviceCount: Int,
        adjustedDeviceCount: Int,
        guestDeviceCount: Int,
        rev: Int,
        createdAt: String,
        updatedAt: String,
        updatedBy: String?,
        hasRemotePin: Bool,
        remotePinFixed: Bool,
        sceneHints: [SceneHint]? = nil,
        hubRemotePairing: RestProfileHubRemotePairing? = nil
    ) {
        self.id = id
        self.name = name
        self.kind = kind
        self.description = description
        self.icon = icon
        self.color = color
        self.childProtection = childProtection
        self.rules = rules
        self.fixed = fixed
        self.userChoice = userChoice
        self.origin = origin
        self.suggestionUpdate = suggestionUpdate
        self.catalogDefaults = catalogDefaults
        self.defaultFor = defaultFor
        self.deviceCount = deviceCount
        self.adjustedDeviceCount = adjustedDeviceCount
        self.guestDeviceCount = guestDeviceCount
        self.rev = rev
        self.createdAt = createdAt
        self.updatedAt = updatedAt
        self.updatedBy = updatedBy
        self.hasRemotePin = hasRemotePin
        self.remotePinFixed = remotePinFixed
        self.sceneHints = sceneHints
        self.hubRemotePairing = hubRemotePairing
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        id = try c.decode(String.self, forKey: "id")
        name = try c.decode(String.self, forKey: "name")
        kind = try c.decode(ProfileKind.self, forKey: "kind")
        description = try c.decode(String?.self, forKey: "description")
        icon = try c.decode(String?.self, forKey: "icon")
        color = try c.decode(String?.self, forKey: "color")
        childProtection = try c.decode(Bool.self, forKey: "child_protection")
        rules = try c.decode(ProfileRuleValues.self, forKey: "rules")
        fixed = try c.decode([ProfileRuleKey].self, forKey: "fixed")
        userChoice = try c.decode([ProfileRuleKey].self, forKey: "user_choice")
        origin = try c.decode(RestProfileOrigin?.self, forKey: "origin")
        suggestionUpdate = try c.decode(RestProfileSuggestionUpdate?.self, forKey: "suggestion_update")
        catalogDefaults = try c.decode([ProfileRuleKey].self, forKey: "catalog_defaults")
        defaultFor = try c.decode([DefaultProfileSlot].self, forKey: "default_for")
        deviceCount = try c.decode(Int.self, forKey: "device_count")
        adjustedDeviceCount = try c.decode(Int.self, forKey: "adjusted_device_count")
        guestDeviceCount = try c.decode(Int.self, forKey: "guest_device_count")
        rev = try c.decode(Int.self, forKey: "rev")
        createdAt = try c.decode(String.self, forKey: "created_at")
        updatedAt = try c.decode(String.self, forKey: "updated_at")
        updatedBy = try c.decode(String?.self, forKey: "updated_by")
        hasRemotePin = try c.decode(Bool.self, forKey: "has_remote_pin")
        remotePinFixed = try c.decode(Bool.self, forKey: "remote_pin_fixed")
        sceneHints = try c.decodeIfPresent([SceneHint].self, forKey: "scene_hints")
        hubRemotePairing = try c.decodeIfPresent(RestProfileHubRemotePairing.self, forKey: "hub_remote_pairing")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(id, forKey: "id")
        try c.encode(name, forKey: "name")
        try c.encode(kind, forKey: "kind")
        try c.encode(description, forKey: "description")
        try c.encode(icon, forKey: "icon")
        try c.encode(color, forKey: "color")
        try c.encode(childProtection, forKey: "child_protection")
        try c.encode(rules, forKey: "rules")
        try c.encode(fixed, forKey: "fixed")
        try c.encode(userChoice, forKey: "user_choice")
        try c.encode(origin, forKey: "origin")
        try c.encode(suggestionUpdate, forKey: "suggestion_update")
        try c.encode(catalogDefaults, forKey: "catalog_defaults")
        try c.encode(defaultFor, forKey: "default_for")
        try c.encode(deviceCount, forKey: "device_count")
        try c.encode(adjustedDeviceCount, forKey: "adjusted_device_count")
        try c.encode(guestDeviceCount, forKey: "guest_device_count")
        try c.encode(rev, forKey: "rev")
        try c.encode(createdAt, forKey: "created_at")
        try c.encode(updatedAt, forKey: "updated_at")
        try c.encode(updatedBy, forKey: "updated_by")
        try c.encode(hasRemotePin, forKey: "has_remote_pin")
        try c.encode(remotePinFixed, forKey: "remote_pin_fixed")
        try c.encodeIfPresent(sceneHints, forKey: "scene_hints")
        try c.encodeIfPresent(hubRemotePairing, forKey: "hub_remote_pairing")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/id", id, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/name", name, .init(pattern: #"^[^\u0000-\u001f]+\z"#, minLength: 1, maxLength: 40))
        ContractCheck.nested(&v_, path + "/kind", kind)
        ContractCheck.string(&v_, path + "/description", description, .init(maxLength: 300))
        ContractCheck.string(&v_, path + "/icon", icon, .init(pattern: #"^mdi:[a-z0-9]+(-[a-z0-9]+)*\z"#))
        ContractCheck.string(&v_, path + "/color", color, .init(pattern: #"^#[0-9A-Fa-f]{6}\z"#))
        ContractCheck.nested(&v_, path + "/rules", rules)
        ContractCheck.items(&v_, path + "/fixed", fixed, unique: true)
        ContractCheck.nested(&v_, path + "/fixed", fixed)
        ContractCheck.items(&v_, path + "/user_choice", userChoice, unique: true)
        ContractCheck.nested(&v_, path + "/user_choice", userChoice)
        ContractCheck.nested(&v_, path + "/origin", origin)
        ContractCheck.nested(&v_, path + "/suggestion_update", suggestionUpdate)
        ContractCheck.items(&v_, path + "/catalog_defaults", catalogDefaults, unique: true)
        ContractCheck.nested(&v_, path + "/catalog_defaults", catalogDefaults)
        ContractCheck.items(&v_, path + "/default_for", defaultFor, unique: true)
        ContractCheck.nested(&v_, path + "/default_for", defaultFor)
        ContractCheck.number(&v_, path + "/device_count", deviceCount, minimum: 0)
        ContractCheck.number(&v_, path + "/adjusted_device_count", adjustedDeviceCount, minimum: 0)
        ContractCheck.number(&v_, path + "/guest_device_count", guestDeviceCount, minimum: 0)
        ContractCheck.number(&v_, path + "/rev", rev, minimum: 1)
        ContractCheck.string(&v_, path + "/updated_by", updatedBy, .init(maxLength: 100))
        ContractCheck.items(&v_, path + "/scene_hints", sceneHints, maxItems: 50)
        ContractCheck.nested(&v_, path + "/scene_hints", sceneHints)
        ContractCheck.nested(&v_, path + "/hub_remote_pairing", hubRemotePairing)
        return v_
    }
}

public struct RestProfileAuditResponseEntriesItem: ContractValue {
    /// Increasing per hub.
    public var id: Int
    public var ts: String
    public var action: ProfileAuditAction
    /// Who made the change: HA user name of the admin, "integration", the brand name for expired
    /// adjustments, "Migration v9"; null = unknown.
    public var actor: String?
    public var profileId: String?
    public var clientId: String?
    /// Rule of override_* entries.
    public var rule: ProfileRuleKey?
    /// State before (shape per action, e.g. {value, expires_at} for override_*, {profile_id} for
    /// profile_assigned, {own_area_id} for own_area_set, the profile for profile_updated); null = none.
    public var before: JSONValue?
    /// State after, same shapes as before; null = none (deleted, expired).
    public var after: JSONValue?
    /// Note of the adjustment, "bulk", "Migration v9" or null.
    public var note: String?

    public init(
        id: Int,
        ts: String,
        action: ProfileAuditAction,
        actor: String?,
        profileId: String?,
        clientId: String?,
        rule: ProfileRuleKey?,
        before: JSONValue?,
        after: JSONValue?,
        note: String?
    ) {
        self.id = id
        self.ts = ts
        self.action = action
        self.actor = actor
        self.profileId = profileId
        self.clientId = clientId
        self.rule = rule
        self.before = before
        self.after = after
        self.note = note
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        id = try c.decode(Int.self, forKey: "id")
        ts = try c.decode(String.self, forKey: "ts")
        action = try c.decode(ProfileAuditAction.self, forKey: "action")
        actor = try c.decode(String?.self, forKey: "actor")
        profileId = try c.decode(String?.self, forKey: "profile_id")
        clientId = try c.decode(String?.self, forKey: "client_id")
        rule = try c.decode(ProfileRuleKey?.self, forKey: "rule")
        before = try c.decode(JSONValue?.self, forKey: "before")
        after = try c.decode(JSONValue?.self, forKey: "after")
        note = try c.decode(String?.self, forKey: "note")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(id, forKey: "id")
        try c.encode(ts, forKey: "ts")
        try c.encode(action, forKey: "action")
        try c.encode(actor, forKey: "actor")
        try c.encode(profileId, forKey: "profile_id")
        try c.encode(clientId, forKey: "client_id")
        try c.encode(rule, forKey: "rule")
        try c.encode(before, forKey: "before")
        try c.encode(after, forKey: "after")
        try c.encode(note, forKey: "note")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.number(&v_, path + "/id", id, minimum: 1)
        ContractCheck.nested(&v_, path + "/action", action)
        ContractCheck.string(&v_, path + "/profile_id", profileId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.string(&v_, path + "/client_id", clientId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.nested(&v_, path + "/rule", rule)
        return v_
    }
}

/// Admin only: history of the profile model with before/after, newest first ("Verlauf" of the
/// device page and the profile editor). Query client_id and/or profile_id filter, limit 1–500
/// (default 100). Persistent in the hub (table profile_audit). The remote PIN never appears
/// (remote_pin_set/profile_remote_pin_set carry only whether a PIN is set).
/// Schema: `schemas/rest/profile-audit.response.json`.
