    /// One sentence for the profile card.
    public var description: String?
    public var icon: String?
    public var color: String?
    public var childProtection: Bool?
    public var rules: ProfileRuleValues?
    public var fixed: [ProfileRuleKey]?
    public var userChoice: [ProfileRuleKey]?
    /// Profile remote PIN: exactly 8 digits, stored only as PBKDF2 hash + salt
    /// (fixtures/crypto/settings-pin-vectors); null removes it. Never in log, audit, diff or preview
    /// (the audit only notes profile_remote_pin_set).
    public var remotePin: String?
    public var remotePinFixed: Bool?

    public init(
        name: String? = nil,
        kind: ProfileKind? = nil,
        description: String? = nil,
        icon: String? = nil,
        color: String? = nil,
        childProtection: Bool? = nil,
        rules: ProfileRuleValues? = nil,
        fixed: [ProfileRuleKey]? = nil,
        userChoice: [ProfileRuleKey]? = nil,
        remotePin: String? = nil,
        remotePinFixed: Bool? = nil
    ) {
        self.name = name
        self.kind = kind
        self.description = description
        self.icon = icon
        self.color = color
        self.childProtection = childProtection
        self.rules = rules
        self.fixed = fixed
        self.userChoice = userChoice
        self.remotePin = remotePin
        self.remotePinFixed = remotePinFixed
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        name = try c.decodeIfPresent(String.self, forKey: "name")
        kind = try c.decodeIfPresent(ProfileKind.self, forKey: "kind")
        description = try c.decodeIfPresent(String.self, forKey: "description")
        icon = try c.decodeIfPresent(String.self, forKey: "icon")
        color = try c.decodeIfPresent(String.self, forKey: "color")
        childProtection = try c.decodeIfPresent(Bool.self, forKey: "child_protection")
        rules = try c.decodeIfPresent(ProfileRuleValues.self, forKey: "rules")
        fixed = try c.decodeIfPresent([ProfileRuleKey].self, forKey: "fixed")
        userChoice = try c.decodeIfPresent([ProfileRuleKey].self, forKey: "user_choice")
        remotePin = try c.decodeIfPresent(String.self, forKey: "remote_pin")
        remotePinFixed = try c.decodeIfPresent(Bool.self, forKey: "remote_pin_fixed")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encodeIfPresent(name, forKey: "name")
        try c.encodeIfPresent(kind, forKey: "kind")
        try c.encodeIfPresent(description, forKey: "description")
        try c.encodeIfPresent(icon, forKey: "icon")
        try c.encodeIfPresent(color, forKey: "color")
        try c.encodeIfPresent(childProtection, forKey: "child_protection")
        try c.encodeIfPresent(rules, forKey: "rules")
        try c.encodeIfPresent(fixed, forKey: "fixed")
        try c.encodeIfPresent(userChoice, forKey: "user_choice")
        try c.encodeIfPresent(remotePin, forKey: "remote_pin")
        try c.encodeIfPresent(remotePinFixed, forKey: "remote_pin_fixed")
    }

    /// Debug output without the values of sensitive fields (`x-sensitive`).
    public var customMirror: Mirror {
        Mirror(self, children: ["name": name as Any, "kind": kind as Any, "description": description as Any, "icon": icon as Any, "color": color as Any, "childProtection": childProtection as Any, "rules": rules as Any, "fixed": fixed as Any, "userChoice": userChoice as Any, "remotePin": "<redacted>", "remotePinFixed": remotePinFixed as Any], displayStyle: .struct)
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/name", name, .init(pattern: #"^[^\u0000-\u001f]+\z"#, minLength: 1, maxLength: 40))
        ContractCheck.nested(&v_, path + "/kind", kind)
        ContractCheck.string(&v_, path + "/description", description, .init(maxLength: 300))
        ContractCheck.string(&v_, path + "/icon", icon, .init(pattern: #"^mdi:[a-z0-9]+(-[a-z0-9]+)*\z"#))
        ContractCheck.string(&v_, path + "/color", color, .init(pattern: #"^#[0-9A-Fa-f]{6}\z"#))
        ContractCheck.nested(&v_, path + "/rules", rules)
        ContractCheck.items(&v_, path + "/fixed", fixed, unique: true)
        ContractCheck.nested(&v_, path + "/fixed", fixed)
        ContractCheck.items(&v_, path + "/user_choice", userChoice, unique: true)
        ContractCheck.nested(&v_, path + "/user_choice", userChoice)
        ContractCheck.string(&v_, path + "/remote_pin", remotePin, .init(pattern: #"^[0-9]{8}\z"#))
        return v_
    }
}

