/// Answer to tag_resolve. tag only with result ok: name and action (show, toggle, turn_on,
/// turn_off, run). The hub checks the rule scan_tags (tags_off, also for guests) and that the
/// target is inside the device's areas (not_visible); quick access levels and the control path
/// apply when the app switches. Pro is checked by the app.
/// Schema: `schemas/ws/server/tag_result.json`.
public struct ServerTagResult: ContractValue {
    public static let type = "tag_result"
    public var tagId: String
    public var result: TagScanResult
    public var tag: ServerTagResultTag?
    /// rate_limited only.
    public var retryAfter: Int?

    public init(
        tagId: String,
        result: TagScanResult,
        tag: ServerTagResultTag? = nil,
        retryAfter: Int? = nil
    ) {
        self.tagId = tagId
        self.result = result
        self.tag = tag
        self.retryAfter = retryAfter
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        tagId = try c.decode(String.self, forKey: "tag_id")
        result = try c.decode(TagScanResult.self, forKey: "result")
        tag = try c.decodeIfPresent(ServerTagResultTag.self, forKey: "tag")
        retryAfter = try c.decodeIfPresent(Int.self, forKey: "retry_after")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(tagId, forKey: "tag_id")
        try c.encode(result, forKey: "result")
        try c.encodeIfPresent(tag, forKey: "tag")
        try c.encodeIfPresent(retryAfter, forKey: "retry_after")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/tag_id", tagId, .init(pattern: #"^[A-Za-z0-9_-]{22}\z"#))
        ContractCheck.nested(&v_, path + "/result", result)
        ContractCheck.nested(&v_, path + "/tag", tag)
        ContractCheck.number(&v_, path + "/retry_after", retryAfter, minimum: 1)
        var present_ = Set<String>()
        present_.insert("tag_id")
        present_.insert("result")
        if tag != nil { present_.insert("tag") }
        if retryAfter != nil { present_.insert("retry_after") }
        let c0_ = ["ok"].contains(result.rawValue)
        ContractCheck.object(&v_, path, present: present_, conditionals: [(matched: c0_, thenRequired: ["tag"], thenForbidden: [], elseRequired: [], elseForbidden: ["tag"])])
        return v_
    }
}

/// The app is too old for this hub: its protocol_version is missing or below min_protocol_version
/// (reason 'protocol'), or its app_version is below min_app_version[platform] (reason
/// 'app_version'). Answer to auth or pair; the hub closes the connection with 4426 right after. The
/// app must not reconnect in a loop and must not reset its pairing: it shows a localized 'Please
/// update the app' hint built from reason, and retries only after an app update or a manual retry.
/// message is an English fallback for logs.
/// Schema: `schemas/ws/server/upgrade_required.json`.
public struct ServerUpgradeRequired: ContractValue {
    public static let type = "upgrade_required"
