        self.platform = platform
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        reason = try c.decode(UpgradeReason.self, forKey: "reason")
        message = try c.decode(String.self, forKey: "message")
        protocolVersion = try c.decode(Int.self, forKey: "protocol_version")
        minProtocolVersion = try c.decode(Int.self, forKey: "min_protocol_version")
        minAppVersion = try c.decode(MinAppVersion.self, forKey: "min_app_version")
        platform = try c.decodeIfPresent(Platform.self, forKey: "platform")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(reason, forKey: "reason")
        try c.encode(message, forKey: "message")
        try c.encode(protocolVersion, forKey: "protocol_version")
        try c.encode(minProtocolVersion, forKey: "min_protocol_version")
        try c.encode(minAppVersion, forKey: "min_app_version")
        try c.encodeIfPresent(platform, forKey: "platform")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.nested(&v_, path + "/reason", reason)
        ContractCheck.number(&v_, path + "/protocol_version", protocolVersion, minimum: 1)
        ContractCheck.number(&v_, path + "/min_protocol_version", minProtocolVersion, minimum: 1)
        ContractCheck.nested(&v_, path + "/min_app_version", minAppVersion)
        ContractCheck.nested(&v_, path + "/platform", platform)
        return v_
    }
}

/// Exactly with status ready (tools/validate.py). HPKE base mode (RFC 9180, DHKEM(X25519,
/// HKDF-SHA256), HKDF-SHA256, ChaCha20Poly1305) to the public key the watch paired with
/// (onboard_start of its phone); info = "hub/watch-access/v1", aad = client_id as ASCII. Plaintext:
/// crypto/watch-access-plaintext.json. Known-answer vector: fixtures/crypto/onboard-seal-vectors
/// case watch-access-v1.
public struct ServerWatchAccessSealed: ContractValue {
    public var suite: String
    /// HPKE encapsulated key (32 bytes), base64url without padding.
    public var enc: String
    /// AEAD ciphertext incl. 16-byte tag, base64url without padding.
    public var ciphertext: String

    public init(
        suite: String,
        enc: String,
        ciphertext: String
    ) {
        self.suite = suite
        self.enc = enc
        self.ciphertext = ciphertext
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        suite = try c.decode(String.self, forKey: "suite")
        enc = try c.decode(String.self, forKey: "enc")
        ciphertext = try c.decode(String.self, forKey: "ciphertext")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(suite, forKey: "suite")
        try c.encode(enc, forKey: "enc")
        try c.encode(ciphertext, forKey: "ciphertext")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/suite", suite, const: "X25519-SHA256-ChaCha20Poly1305")
        ContractCheck.string(&v_, path + "/enc", enc, .init(pattern: #"^[A-Za-z0-9_-]{43}\z"#))
        ContractCheck.string(&v_, path + "/ciphertext", ciphertext, .init(pattern: #"^[A-Za-z0-9_-]+\z"#, maxLength: 262144))
        return v_
    }
}

/// The Home Assistant access of a watch, sealed to the watch's key. Answer to watch_access_get, and
/// pushed unasked to every connection of the device that set the watch up when the watch's access
/// changes (new or rotated HA token, profile, rules, remote access, access hours). The phone passes
/// sealed on unchanged; it cannot open it. status: ready = sealed carries the watch's
/// client_config; pending = the watch holds a key that is not usable yet: not issued, or held back
/// until the integration has the watch's rules, or being replaced (client_config.token_error); a
/// push follows; gone = there is no watch of this device with this id (deleted, locked, or set up
/// by another device): the watch forgets its access.
/// Schema: `schemas/ws/server/watch_access.json`.
public struct ServerWatchAccess: ContractValue, CustomReflectable {
    public static let type = "watch_access"
    public var clientId: String
    public var status: ServerWatchAccessStatus
    /// Exactly with status ready (tools/validate.py). HPKE base mode (RFC 9180, DHKEM(X25519,
    /// HKDF-SHA256), HKDF-SHA256, ChaCha20Poly1305) to the public key the watch paired with
    /// (onboard_start of its phone); info = "hub/watch-access/v1", aad = client_id as ASCII. Plaintext:
    /// crypto/watch-access-plaintext.json. Known-answer vector: fixtures/crypto/onboard-seal-vectors
    /// case watch-access-v1.
    public var sealed: ServerWatchAccessSealed?
    /// Only with status gone for a child's watch the hub removed with a write: why (the phone tells its
    /// user). The hub keeps it for that phone, so a phone that was offline gets it with the gone it
    /// fetches later (watch_access_get). Missing = no reason given.
    public var reason: WatchRemovedReason?

    public init(
        clientId: String,
        status: ServerWatchAccessStatus,
        sealed: ServerWatchAccessSealed? = nil,
        reason: WatchRemovedReason? = nil
    ) {
        self.clientId = clientId
        self.status = status
        self.sealed = sealed
        self.reason = reason
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        try c.expectConstant(Self.type, forKey: "type")
        clientId = try c.decode(String.self, forKey: "client_id")
        status = try c.decode(ServerWatchAccessStatus.self, forKey: "status")
        sealed = try c.decodeIfPresent(ServerWatchAccessSealed.self, forKey: "sealed")
        reason = try c.decodeIfPresent(WatchRemovedReason.self, forKey: "reason")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encode(Self.type, forKey: "type")
        try c.encode(clientId, forKey: "client_id")
        try c.encode(status, forKey: "status")
        try c.encodeIfPresent(sealed, forKey: "sealed")
        try c.encodeIfPresent(reason, forKey: "reason")
    }

    /// Debug output without the values of sensitive fields (`x-sensitive`).
    public var customMirror: Mirror {
        Mirror(self, children: ["clientId": clientId as Any, "status": status as Any, "sealed": "<redacted>", "reason": reason as Any], displayStyle: .struct)
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/client_id", clientId, .init(pattern: #"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\z"#))
        ContractCheck.nested(&v_, path + "/status", status)
        ContractCheck.nested(&v_, path + "/sealed", sealed)
        ContractCheck.nested(&v_, path + "/reason", reason)
        return v_
    }
}

/// Writable tile settings of an area entity placement. Every field is optional; null or absent =
/// app default. Allowed values per domain: data/tile-capabilities.json (the hub answers 422 for
/// anything else). Clients MUST fall back to the default for unknown enum values and for values not
/// allowed for the domain. The hub always delivers the settings; an app may show the standard card
/// instead (guests always do).
public struct TileSettingsBase: ContractValue {
    /// null = Home Assistant icon (attributes.icon), else the app's domain/state symbol. A custom icon
    /// is static (replaces the state-dependent symbol).
    public var icon: String?
    public var variant: TileVariant?
    public var secondary: TileSecondary?
    public var tapAction: TileTapAction?
    public var holdAction: TileHoldAction?
    /// Ask before toggle/run. Locks and alarm panels always confirm (field not allowed there).
    public var confirm: Bool?
    /// Palette color family, applied only while the entity is active. null = domain tint.
    public var accent: TileAccent?
    /// Form factors that do not show this card (1-2 entries; all three = use is_visible). Filtered by
    /// the app, not a security boundary.
    public var hiddenOn: [TileFormFactor]?

    public init(
        icon: String? = nil,
        variant: TileVariant? = nil,
        secondary: TileSecondary? = nil,
        tapAction: TileTapAction? = nil,
        holdAction: TileHoldAction? = nil,
        confirm: Bool? = nil,
        accent: TileAccent? = nil,
        hiddenOn: [TileFormFactor]? = nil
    ) {
        self.icon = icon
        self.variant = variant
        self.secondary = secondary
        self.tapAction = tapAction
        self.holdAction = holdAction
        self.confirm = confirm
        self.accent = accent
        self.hiddenOn = hiddenOn
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: ContractCodingKey.self)
        icon = try c.decodeIfPresent(String.self, forKey: "icon")
        variant = try c.decodeIfPresent(TileVariant.self, forKey: "variant")
        secondary = try c.decodeIfPresent(TileSecondary.self, forKey: "secondary")
        tapAction = try c.decodeIfPresent(TileTapAction.self, forKey: "tap_action")
        holdAction = try c.decodeIfPresent(TileHoldAction.self, forKey: "hold_action")
        confirm = try c.decodeIfPresent(Bool.self, forKey: "confirm")
        accent = try c.decodeIfPresent(TileAccent.self, forKey: "accent")
        hiddenOn = try c.decodeIfPresent([TileFormFactor].self, forKey: "hidden_on")
    }

    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: ContractCodingKey.self)
        try c.encodeIfPresent(icon, forKey: "icon")
        try c.encodeIfPresent(variant, forKey: "variant")
        try c.encodeIfPresent(secondary, forKey: "secondary")
        try c.encodeIfPresent(tapAction, forKey: "tap_action")
        try c.encodeIfPresent(holdAction, forKey: "hold_action")
        try c.encodeIfPresent(confirm, forKey: "confirm")
        try c.encodeIfPresent(accent, forKey: "accent")
        try c.encodeIfPresent(hiddenOn, forKey: "hidden_on")
    }

    public func validate(at path: String) -> [ContractViolation] {
        var v_: [ContractViolation] = []
        ContractCheck.string(&v_, path + "/icon", icon, .init(pattern: #"^(mdi:[a-z0-9]+(-[a-z0-9]+)*|sf:[a-z0-9]+(\.[a-z0-9]+)*)\z"#, maxLength: 100))
        ContractCheck.nested(&v_, path + "/variant", variant)
        ContractCheck.nested(&v_, path + "/secondary", secondary)
        ContractCheck.nested(&v_, path + "/tap_action", tapAction)
        ContractCheck.nested(&v_, path + "/hold_action", holdAction)
        ContractCheck.nested(&v_, path + "/accent", accent)
        ContractCheck.items(&v_, path + "/hidden_on", hiddenOn, minItems: 1, maxItems: 2, unique: true)
        ContractCheck.nested(&v_, path + "/hidden_on", hiddenOn)
        return v_
    }
}
